<dialog id="source-picker" aria-labelledby="picker-title"><div class="pool-section-head"><h2 id="picker-title">Choose sources</h2><button type="button" id="picker-close" class="btn-crm-secondary" aria-label="Close source picker"><i class="bi bi-x-lg" aria-hidden="true"></i></button></div><p class="field-note">Your chosen items stay selected while you search. Closing this window keeps the previous range.</p><div id="picker-selected"></div><label for="picker-search" class="form-label mt-3">Search sources</label><input id="picker-search" type="search" class="form-control" placeholder="Enter a keyword to search…" maxlength="100" autocomplete="off"><div id="picker-results" class="mt-3" aria-live="polite"></div><div class="picker-footer"><span id="picker-count"></span><button type="button" class="btn-crm-primary" id="picker-done">Use selected items</button></div></dialog>
